class Solution {
    int gcd(int a, int b) {
        while (b) {
            a %= b;
            swap(a, b);
        }
        return a;
    }
public:
    vector<string> simplifiedFractions(int n) {
        vector<string> res;
        for (int d = 2; d <= n; ++d) {
            for (int nu = 1; nu < d; ++nu) {
                if (gcd(nu, d) == 1) {
                    res.push_back(to_string(nu) + "/" + to_string(d));
                }
            }
        }
        return res;
    }
};
